import test from 'node:test';
import assert from 'node:assert/strict';
import { dashboard } from '../src/reports.js';

test('dashboard with empty invoices', () => {
  const result = dashboard([], '2026-10-31');
  assert.deepEqual(result.counts, { draft: 0, issued: 0, partially_paid: 0, paid: 0 });
  assert.equal(result.outstanding, 0);
  assert.equal(result.overdue.count, 0);
  assert.equal(result.overdue.amount, 0);
  assert.deepEqual(result.topCustomers, []);
});

test('dashboard counts invoices by status', () => {
  const invoices = [
    {
      customerId: 'C-001',
      issueDate: '2026-10-01',
      dueDate: '2026-10-31',
      status: 'draft',
      lines: [{ sku: 'ITEM', qty: 1, unitPrice: 1000, name: 'Item', vatRate: 21, discountPercent: 0 }],
    },
    {
      customerId: 'C-001',
      number: 'INV-2026-0001',
      issueDate: '2026-10-05',
      dueDate: '2026-11-04',
      status: 'issued',
      lines: [{ sku: 'ITEM', qty: 1, unitPrice: 1000, name: 'Item', vatRate: 21, discountPercent: 0 }],
    },
    {
      customerId: 'C-001',
      number: 'INV-2026-0002',
      issueDate: '2026-09-01',
      dueDate: '2026-10-01',
      status: 'partially_paid',
      payments: [{ amount: 50000, date: '2026-09-15' }],
      lines: [{ sku: 'ITEM', qty: 1, unitPrice: 100000, name: 'Item', vatRate: 21, discountPercent: 0 }],
    },
    {
      customerId: 'C-001',
      number: 'INV-2026-0003',
      issueDate: '2026-08-01',
      dueDate: '2026-09-01',
      status: 'paid',
