    {
      customerId: 'C-001',
      number: 'INV-2026-0002',
      issueDate: '2026-10-05',
      dueDate: '2026-11-04',
      status: 'partially_paid',
      payments: [{ amount: 50000, date: '2026-10-10' }],
      lines: [{ sku: 'ITEM', qty: 5, unitPrice: 10000, name: 'Item', vatRate: 21, discountPercent: 0 }],
    },
    {
      customerId: 'C-001',
      number: 'INV-2026-0003',
      issueDate: '2026-09-01',
      dueDate: '2026-10-01',
      status: 'paid',
      payments: [{ amount: 121000, date: '2026-09-20' }],
      lines: [{ sku: 'ITEM', qty: 1, unitPrice: 100000, name: 'Item', vatRate: 21, discountPercent: 0 }],
    },
  ];
  const result = dashboard(invoices, '2026-10-31');
  assert(result.outstanding > 0);
});

test('dashboard identifies overdue invoices', () => {
  const invoices = [
    {
      customerId: 'C-001',
      number: 'INV-2026-0001',
      issueDate: '2026-10-01',
      dueDate: '2026-10-10',
      status: 'issued',
      lines: [{ sku: 'ITEM', qty: 1, unitPrice: 1000, name: 'Item', vatRate: 21, discountPercent: 0 }],
